static const int kHalleyN = int(sizeof(kHalley) / sizeof(kHalley[0]));
static const double kHalleyRkm = 5.5;              // Horizons' RAD (the nucleus is about 15 x 8 km)
static const double kHalleyM1 = 5.5, kHalleyK1 = 8.0;   // Horizons' total-magnitude law, M1 and k1

static bool ephHalleySpan(double jdTT) { return ephOscSpan(kHalley, kHalleyN, jdTT); }
static void ephHalleyHelio(double jdTT, double xyz[3]) { ephOscHelio(kHalley, kHalleyN, jdTT, xyz); }
static void ephHalleyOrbit(double jdTT, double Mdeg, double xyz[3]) { ephOscOrbit(kHalley, kHalleyN, jdTT, Mdeg, xyz); }

// A comet's total (nucleus + coma) magnitude at heliocentric distance r and geocentric distance d (AU):
// Horizons' T-mag = M1 + 5 log10(d) + k1 log10(r).
static double ephCometMag(double M1, double k1, double r, double d) {
	return M1 + 5.0 * std::log10(d) + k1 * std::log10(r);
}
